import{_ as i}from"./chunks/mp_yudaoyuanma3.BZ25Ig7i.js";import{_ as r,a as t}from"./chunks/02.WVnmoTOm.js";import{_ as o}from"./chunks/数据库依赖.2MFhGZpe.js";import{_ as s}from"./chunks/ruoyi-vue-pro-architecture.DOjiZwIR.js";import{_ as l,o as p,c as n,a2 as h}from"./chunks/framework.CqGPl1zp.js";const e="/newx-doc/img/%E5%90%8E%E7%AB%AF%E6%89%8B%E5%86%8C/%E5%BF%AB%E9%80%9F%E5%90%AF%E5%8A%A8/Star.png",d="/newx-doc/img/%E5%BF%AB%E9%80%9F%E5%90%AF%E5%8A%A8/%E5%BF%AB%E9%80%9F%E5%90%AF%E5%8A%A8.png",c="/newx-doc/img/_ext/8679e847181e0b05.png",u="/newx-doc/img/_ext/0d3ef095b8f21e32.png",m="/newx-doc/img/%E5%90%8E%E7%AB%AF%E6%89%8B%E5%86%8C/%E5%BF%AB%E9%80%9F%E5%90%AF%E5%8A%A8/%E5%90%8E%E7%AB%AF%E7%BC%96%E8%AF%91.png",k="/newx-doc/img/_ext/96a188bbd3aae915.png",g="/newx-doc/img/%E5%BF%AB%E9%80%9F%E5%90%AF%E5%8A%A8/01.png",E="/newx-doc/img/%E5%BF%AB%E9%80%9F%E5%90%AF%E5%8A%A8/%E6%BC%94%E7%A4%BA%E9%A1%B9%E7%9B%AE.png",C=JSON.parse('{"title":"快速启动（后端项目）","description":"","frontmatter":{},"headers":[],"relativePath":"quick-start.md","filePath":"quick-start.md","lastUpdated":null}'),b={name:"quick-start.md"};function f(_,a,y,A,q,v){return p(),n("div",null,[...a[0]||(a[0]=[h('<h1 id="快速启动-后端项目" tabindex="-1">快速启动（后端项目） <a class="header-anchor" href="#快速启动-后端项目" aria-label="Permalink to &quot;快速启动（后端项目）&quot;">​</a></h1><p>目标：使用 IDEA 工具，将项目 <a href="https://github.com/YunaiV/ruoyi-vue-pro" target="_blank" rel="noreferrer">ruoyi-vue-pro</a> 的后端项目运行起来 🛫</p><p>整个过程非常简单，预计 10 分钟就可以完成，取决于大家的网速。</p><blockquote><p>↓↓↓ 技术交流群，一起苦练技术基本功，每日精进 30 公里！↓↓↓</p></blockquote><p><img src="'+i+'" alt="交流群"></p><h2 id="👍-相关视频教程" tabindex="-1">👍 相关视频教程 <a class="header-anchor" href="#👍-相关视频教程" aria-label="Permalink to &quot;👍 相关视频教程&quot;">​</a></h2><ul><li><a href="https://t.zsxq.com/07BeiEA6Q" target="_blank" rel="noreferrer">从零开始 02：在 Windows 环境下，如何运行前后端项目？</a></li><li><a href="https://t.zsxq.com/07FUNnYFm" target="_blank" rel="noreferrer">从零开始 03：在 MacOS 环境下，如何运行前后端项目？</a></li></ul><h2 id="_1-克隆代码" tabindex="-1">1. 克隆代码 <a class="header-anchor" href="#_1-克隆代码" aria-label="Permalink to &quot;1. 克隆代码&quot;">​</a></h2><p>使用 <a href="http://www.iocoder.cn/categories/IDEA/?self" target="_blank" rel="noreferrer">IDEA</a> 克隆 <a href="https://github.com/YunaiV/ruoyi-vue-pro" target="_blank" rel="noreferrer">https://github.com/YunaiV/ruoyi-vue-pro</a> 仓库的最新代码，并给该仓库一个 <a href="https://github.com/YunaiV/ruoyi-vue-pro" target="_blank" rel="noreferrer">Star</a> 。</p><blockquote><p>注意：不建议使用 Eclipse，因为它没有支持 Lombok 和 Mapstruct 插件。</p></blockquote><p>克隆完成后，耐心等待 Maven 下载完相关的依赖。一定要注意：</p><ul><li>① 默认情况下，使用 <code>master</code> 分支，它对应 JDK 8 + Spring Boot 2.7 版本。</li><li>② 如果你想体验 JDK 17/21 + Spring Boot 3.5 版本，需要切换到 <code>master-jdk17</code> 分支。</li><li>③ 如果你想体验 JDK 25 + Spring Boot 4.x 版本，需要切换到 <code>master-jdk25</code> 分支。</li></ul><blockquote><p>友情提示：项目的每个模块的作用，可见 <a href="./project-intro">《开发指南 —— 项目结构》</a> 文档。</p></blockquote><p>使用的 Spring Boot 版本较新，所以需要下载一段时间。趁着这个时间，胖友可以给项目添加一个 <a href="https://github.com/YunaiV/ruoyi-vue-pro" target="_blank" rel="noreferrer">Star</a> ，支持下艿艿。</p><p><img src="'+e+'" alt="Star 一波"></p><h2 id="_2-apifox-接口工具" tabindex="-1">2. Apifox 接口工具 <a class="header-anchor" href="#_2-apifox-接口工具" aria-label="Permalink to &quot;2. Apifox 接口工具&quot;">​</a></h2><p>点击 <a href="https://apifox.com/?utm_source=ydym" target="_blank" rel="noreferrer">Apifox</a> 首页，下载对应的 Apifox 桌面版。如下图所示：</p><p>为什么要下载 Apifox 桌面版？</p><p>艿艿已经卸载 Postman，使用 Apifox 进行替代。国产软件，yyds 永远滴神！</p><p>国内很多互联网公司，包括百度、阿里、腾讯、字节跳动等等在内，都在使用 Apifox 作为 API 工具。</p><p><img src="'+r+'" alt="Apifox 下载"></p><p>解压后，双击进行安装即可。黑色界面，非常酷炫。</p><p><img src="'+t+'" alt="Apifox 界面"></p><p>接口文档？</p><p>阅读 <a href="./api-doc">《开发指南 —— 接口文档》</a> 呀~~</p><h2 id="_3-初始化-mysql" tabindex="-1">3. 初始化 MySQL <a class="header-anchor" href="#_3-初始化-mysql" aria-label="Permalink to &quot;3. 初始化 MySQL&quot;">​</a></h2><p>友情提示？</p><p>如果你是 PostgreSQL、Oracle、SQL Server、DM、大金 等其它数据库，也是可以的。</p><p>因为我主要使用 MySQL数据库为主，所以其它数据库的 SQL 文件可能存在滞后，可以加入 <a href="./qun">用户群</a> 反馈。</p><p>项目使用 MySQL 存储数据，所以需要启动一个 MySQL 服务。</p><p>① 创建一个名字为 <code>ruoyi-vue-pro</code> 数据库，<strong>【只要】</strong> 执行对应数据库类型的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/tree/master/sql" target="_blank" rel="noreferrer"><code>sql</code></a> 目录下的 <code>ruoyi-vue-pro.sql</code> SQL 文件，进行初始化。</p><p><img src="'+d+'" alt="导入 MySQL 数据库"></p><p>② 默认配置下，MySQL 需要启动在 3306 端口，并且账号是 root，密码是 123456。如果不一致，需要修改 <code>application-local.yaml</code> 配置文件。</p><p><img src="'+c+'" alt="修改配置文件"></p><hr><p>疑问：如果我不是 MySQL，想用其它数据库，怎么办？？？</p><ul><li>1、【如果是 PostgreSQL、Oracle、SQL Server 数据库】，修改 <code>yudao-spring-boot-starter-mybatis</code> 模块的 <code>pom.xml</code> 文件，将对应的 JDBC Driver 的 <code>optional</code> 移除（注意，需要使用 IDEA 刷新下 Maven 的依赖）。如下图所示： <img src="'+o+'" alt="数据库依赖"></li><li>2、【如果是 DM 达梦、大金、OpenGauss 等国产信创数据库】建议先使用 MySQL 跑通，然后再阅读 <a href="./xinchuang-db">《国产信创数据库（DM 达梦、大金、OpenGauss）》</a> 文档。</li></ul><h2 id="_4-初始化-redis" tabindex="-1">4. 初始化 Redis <a class="header-anchor" href="#_4-初始化-redis" aria-label="Permalink to &quot;4. 初始化 Redis&quot;">​</a></h2><p>项目使用 Redis 缓存数据，所以需要启动一个 Redis 服务。</p><blockquote><p>不会安装的胖友，可以选择阅读下文，良心的艿艿。</p><ul><li>Windows 安装 Redis 指南：<a href="http://www.iocoder.cn/Redis/windows-install" target="_blank" rel="noreferrer">http://www.iocoder.cn/Redis/windows-install</a></li><li>Mac 安装 Redis 指南：<a href="http://www.iocoder.cn/Redis/mac-install" target="_blank" rel="noreferrer">http://www.iocoder.cn/Redis/mac-install</a></li></ul></blockquote><p>默认配置下，Redis 启动在 6379 端口，不设置账号密码。如果不一致，需要修改 <code>application-local.yaml</code> 配置文件。</p><p><img src="'+u+'" alt="修改配置文件"></p><p>友情提示：</p><p>如果你的项目不希望使用 Redis，可以参考文档 <a href="./remove-redis">《如何去除 Redis 缓存》</a>。</p><h2 id="_5-启动后端项目" tabindex="-1">5. 启动后端项目 <a class="header-anchor" href="#_5-启动后端项目" aria-label="Permalink to &quot;5. 启动后端项目&quot;">​</a></h2><p><a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-server" target="_blank" rel="noreferrer"><code>yudao-server</code></a> 是后端项目，提供管理后台、用户 APP 的 RESTful API 接口。</p><h3 id="_5-1-编译项目" tabindex="-1">5.1 编译项目 <a class="header-anchor" href="#_5-1-编译项目" aria-label="Permalink to &quot;5.1 编译项目&quot;">​</a></h3><p>第一步，使用 IDEA 自带的 Maven 插件，进行项目的编译。如下图所示：</p><p><img src="'+m+`" alt="后端编译"></p><p>【可选】也可以使用 Maven 命令编译：</p><ul><li>使用 IDEA 打开 Terminal 终端，在 <strong>根目录</strong> 下直接执行 <code>mvn clean install package &#39;-Dmaven.test.skip=true&#39;</code> 命令。</li><li>如果执行报 <code>Unknown lifecycle phase “.test.skip=true”</code> 错误，使用 <code>mvn clean install package -Dmaven.test.skip=true</code> 即可。</li></ul><p>ps：只有首次需要执行 Maven 命令，解决基础 <code>pom.xml</code> 不存在，导致报 BaseDbUnitTest 类不存在的问题。</p><p>整个过程，预计需要 1 分钟左右。成功后，控制台日志如下：</p><div class="language-Bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[INFO] ------------------------------------------------------------------------</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[INFO] BUILD SUCCESS</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[INFO] ------------------------------------------------------------------------</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[INFO] Total time:  9.139 s (</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Wall</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Clock</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[INFO] Finished at: 2024-05-03T18:56:03+08:00</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[INFO] ------------------------------------------------------------------------</span></span></code></pre></div><h3 id="_5-2-启动项目" tabindex="-1">5.2 启动项目 <a class="header-anchor" href="#_5-2-启动项目" aria-label="Permalink to &quot;5.2 启动项目&quot;">​</a></h3><p>第二步，执行 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-server/src/main/java/cn/iocoder/yudao/server/YudaoServerApplication.java" target="_blank" rel="noreferrer">YudaoServerApplication</a> 类，进行启动。</p><p>启动还是报类不存在？</p><p>可能是 IDEA 的 bug，点击 [File -&gt; Invalidate Caches] 菜单，清空下缓存，重启后在试试看。</p><p><img src="`+k+`" alt="启动后端项目"></p><p>启动完成后，使用浏览器访问 <a href="http://127.0.0.1:48080" target="_blank" rel="noreferrer">http://127.0.0.1:48080</a> 地址，返回如下 JSON 字符串，说明成功。</p><blockquote><p>友情提示：注意，默认配置下，后端项目启动在 48080 端口。</p></blockquote><div class="language-JSON vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">JSON</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">401</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;msg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;账号未登录&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>如果报 “Command line is too long” 错误，参考 <a href="https://www.iocoder.cn/Fight/Intellij-IDEA-Indicates-that-Command-Line-is-too-long/?yudao" target="_blank" rel="noreferrer">《Intellij IDEA 运行时报 Command line is too long 解决方法 》</a> 文章解决，或者直接点击 YudaoServerApplication <strong>蓝字</strong>部分！</p><p><img src="`+g+'" alt="“Command line is too long” 错误"></p><h3 id="_5-3-启动其它模块" tabindex="-1">5.3 启动其它模块 <a class="header-anchor" href="#_5-3-启动其它模块" aria-label="Permalink to &quot;5.3 启动其它模块&quot;">​</a></h3><p>考虑到启动速度，默认值启动 <code>system</code> 系统服务，<code>infra</code> 基础设施两个模块。如果你需要启动其它模块，可以参考下面的文档：</p><ul><li><a href="./bpm">《工作流手册 —— 工作流》</a></li><li><a href="./mp/build">《公众号手册 —— 功能开启》</a></li><li><a href="./pay/build">《支付手册 —— 功能开启》</a></li><li><a href="./report">《大屏手册 —— 报表设计器》</a></li><li><a href="./member/build">《会员手册 —— 功能开启》</a></li><li><a href="./mall/build">《商城手册 —— 功能开启》</a></li><li><a href="./erp/build">《ERP 手册 —— 功能开启》</a></li><li><a href="./crm/build">《CRM 手册 —— 功能开启》</a></li><li><a href="./mes/build">《MES 手册 —— 功能开启》</a></li><li><a href="./wms/build">《WMS 手册 —— 功能开启》</a></li><li><a href="./hrm/build">《HRM 手册 —— 功能开启》</a></li><li><a href="./fms/build">《FMS 手册 —— 功能开启》</a></li><li><a href="./pms/build">《PMS 手册 —— 功能开启》</a></li><li><a href="./oa/build">《OA 手册 —— 功能开启》</a></li><li><a href="./im/build">《IM 即时通讯手册 —— 功能开启》</a></li><li><a href="./ai/build">《AI 大模型手册 —— 功能开启》</a></li><li><a href="./iot/build">《IoT 物联网手册 —— 功能开启》</a></li></ul><h2 id="_6-启动前端项目【简易】" tabindex="-1">6. 启动前端项目【简易】 <a class="header-anchor" href="#_6-启动前端项目【简易】" aria-label="Permalink to &quot;6. 启动前端项目【简易】&quot;">​</a></h2><p>友情提示：这是可选步骤，想要完整启动前端，可以直接看「7. 启动前端项目【完整】」小节噢！</p><p>在 <a href="https://gitee.com/yudaocode/yudao-demo" target="_blank" rel="noreferrer">yudao-demo</a> 项目中，提前编译好了前端项目的静态资源，无需安装 Node 等前端环境，可以直接体验和使用。操作步骤如下：</p><p>① 克隆 <a href="https://gitee.com/yudaocode/yudao-demo" target="_blank" rel="noreferrer">https://gitee.com/yudaocode/yudao-demo</a> 项目，运行对应的启动类：</p><p><img src="'+E+'" alt="演示项目"></p><ul><li><a href="https://github.com/yudaocode/yudao-ui-admin-vue3" target="_blank" rel="noreferrer">Vue3 + element-plus</a> ：ElementPlusApplication</li><li><a href="https://github.com/yudaocode/yudao-ui-admin-vben" target="_blank" rel="noreferrer">Vue3 + vben</a> ：VbenApplication</li><li><a href="https://github.com/yudaocode/yudao-ui-admin-vben" target="_blank" rel="noreferrer">Vue2 + element-ui</a> ：ElementUIApplication</li></ul><p>② 访问 <a href="http://127.0.0.1:2048/" target="_blank" rel="noreferrer">http://127.0.0.1:2048/</a> 地址，即可看到对应的管理后台。</p><p>补充说明：</p><p>前端项目是不定期编译，可能不是最新版本。</p><p>如果需要最新版本，请继续往下看。</p><h2 id="_7-启动前端项目【完整】" tabindex="-1">7. 启动前端项目【完整】 <a class="header-anchor" href="#_7-启动前端项目【完整】" aria-label="Permalink to &quot;7. 启动前端项目【完整】&quot;">​</a></h2><p>参考 <a href="./quick-start-front">《快速启动（前端项目）》</a> 文档</p><h2 id="_666-彩蛋" tabindex="-1">666. 彩蛋 <a class="header-anchor" href="#_666-彩蛋" aria-label="Permalink to &quot;666. 彩蛋&quot;">​</a></h2><p>至此，我们已经完成了项目 <a href="https://github.com/YunaiV/ruoyi-vue-pro" target="_blank" rel="noreferrer">ruoyi-vue-pro</a> 的启动。</p><p>胖友可以根据自己的兴趣，阅读相关源码。如果你想更快速的学习，可以看看 <a href="./video">《视频教程 》</a> 教程哟。</p><p><img src="'+s+'" alt="架构图"></p><p>后面，艿艿会花大量的时间，继续优化这个项目。同时，输出与项目匹配的技术博客，方便胖友更好的学习与理解。</p><p>还是那句话，😆 为开源继绝学，我辈义不容辞！</p><hr><p>嘿嘿嘿，记得一定要给 <a href="https://github.com/YunaiV/ruoyi-vue-pro" target="_blank" rel="noreferrer">https://github.com/YunaiV/ruoyi-vue-pro</a> 一个 star，这对艿艿真的很重要。</p><p><img src="'+e+'" alt="Star 一波"></p>',88)])])}const I=l(b,[["render",f]]);export{C as __pageData,I as default};
